{
  "name": "ACQ400 模块化高速数据采集系统",
  "name_en": "ACQ400 Modular High-Speed Data Acquisition System",
  "manufacturer": "D-TACQ",
  "description": "一种机箱式模块化高速数据采集与瞬态记录设备，可集成多通道模拟/数字采集模块、触发与同步功能以及板载存储，用于实验中的高速波形采集、事件记录、校准换算和时序控制。",
  "description_en": "A chassis-based modular high-speed data acquisition and transient recording system that can integrate multi-channel analog/digital I/O, trigger and synchronization features, and onboard memory for laboratory waveform capture, event recording, calibration-based scaling, and timing control.",
  "tag_hints": [
    "modular DAQ",
    "transient recorder",
    "high-speed waveform capture",
    "trigger and synchronization",
    "multi-channel acquisition",
    "onboard memory capture",
    "arbitrary waveform generation"
  ],
  "actions": [
    {
      "action_name": "read",
      "description": "读取设备数据端口输出的原始采集数据。",
      "description_en": "Read raw acquired data from a device data port."
    },
    {
      "action_name": "get_blocks",
      "description": "分块获取设备存储的采集数据。",
      "description_en": "Retrieve captured data from device memory in blocks."
    },
    {
      "action_name": "st_monitor",
      "description": "监视设备状态通道并跟踪状态变化。",
      "description_en": "Monitor the device status channel and track state changes."
    },
    {
      "action_name": "get_state",
      "description": "获取当前采集状态。",
      "description_en": "Get the current acquisition state."
    },
    {
      "action_name": "get_pre",
      "description": "获取触发前样本数。",
      "description_en": "Get the number of pre-trigger samples."
    },
    {
      "action_name": "get_post",
      "description": "获取触发后样本数。",
      "description_en": "Get the number of post-trigger samples."
    },
    {
      "action_name": "get_total",
      "description": "获取总样本数。",
      "description_en": "Get the total sample count."
    },
    {
      "action_name": "get_elapsed",
      "description": "获取当前已采集样本数。",
      "description_en": "Get the number of samples acquired so far."
    },
    {
      "action_name": "wait_event",
      "description": "等待设备事件发生。",
      "description_en": "Wait for a device event."
    },
    {
      "action_name": "wait_armed",
      "description": "等待设备进入布防状态。",
      "description_en": "Wait for the device to enter the armed state."
    },
    {
      "action_name": "wait_stopped",
      "description": "等待设备停止采集。",
      "description_en": "Wait for the device to stop acquisition."
    },
    {
      "action_name": "wait_state_changed",
      "description": "等待设备状态改变。",
      "description_en": "Wait for the device state to change."
    },
    {
      "action_name": "init_site_client",
      "description": "初始化对机箱内指定站点或模块的访问。",
      "description_en": "Initialize access to a specific site or module in the chassis."
    },
    {
      "action_name": "make_sa_sd_aliases",
      "description": "建立设备 SA/SD 信号或服务别名。",
      "description_en": "Create SA/SD signal or service aliases for the device."
    },
    {
      "action_name": "get_sys_info",
      "description": "获取设备系统信息。",
      "description_en": "Get device system information."
    },
    {
      "action_name": "close",
      "description": "关闭与设备的连接。",
      "description_en": "Close the connection to the device."
    },
    {
      "action_name": "state",
      "description": "获取当前设备状态。",
      "description_en": "Get the current device state."
    },
    {
      "action_name": "post_samples",
      "description": "获取触发后样本数。",
      "description_en": "Get the number of post-trigger samples."
    },
    {
      "action_name": "pre_samples",
      "description": "获取触发前样本数。",
      "description_en": "Get the number of pre-trigger samples."
    },
    {
      "action_name": "elapsed_samples",
      "description": "获取当前已采集样本数。",
      "description_en": "Get the number of samples acquired so far."
    },
    {
      "action_name": "demux_status",
      "description": "获取数据是否按通道解复用的状态。",
      "description_en": "Get whether data are demultiplexed by channel."
    },
    {
      "action_name": "samples",
      "description": "获取样本总数。",
      "description_en": "Get the total number of samples."
    },
    {
      "action_name": "get_aggregator_sites",
      "description": "获取参与聚合采集的站点或模块列表。",
      "description_en": "Get the list of sites or modules participating in aggregated acquisition."
    },
    {
      "action_name": "get_aggregator_svc_list",
      "description": "获取聚合采集相关的服务列表。",
      "description_en": "Get the list of services used for aggregated acquisition."
    },
    {
      "action_name": "fetch_all_calibration",
      "description": "读取全部模块的校准信息。",
      "description_en": "Fetch calibration data from all modules."
    },
    {
      "action_name": "scale_raw",
      "description": "按校准系数将原始数据缩放到工程量。",
      "description_en": "Scale raw data to engineering units using calibration."
    },
    {
      "action_name": "chan2volts",
      "description": "将通道原始样本转换为电压值。",
      "description_en": "Convert raw channel samples to volts."
    },
    {
      "action_name": "read_chan",
      "description": "读取单个通道的采集数据。",
      "description_en": "Read acquired data from one channel."
    },
    {
      "action_name": "read_decims",
      "description": "读取抽取后的降采样数据。",
      "description_en": "Read decimated data."
    },
    {
      "action_name": "nchan",
      "description": "获取通道数量。",
      "description_en": "Get the number of channels."
    },
    {
      "action_name": "data_size",
      "description": "获取采集数据大小。",
      "description_en": "Get the size of captured data."
    },
    {
      "action_name": "uut_demux_enabled",
      "description": "获取设备是否启用通道解复用。",
      "description_en": "Get whether channel demultiplexing is enabled on the unit."
    },
    {
      "action_name": "read_transient_timebase",
      "description": "读取瞬态采集的时间基准。",
      "description_en": "Read the timebase for transient acquisition."
    },
    {
      "action_name": "load_segments",
      "description": "载入分段采集配置。",
      "description_en": "Load segmented acquisition settings."
    },
    {
      "action_name": "show_segments",
      "description": "显示当前分段采集配置。",
      "description_en": "Show the current segmented acquisition settings."
    },
    {
      "action_name": "clear_counters",
      "description": "清除设备计数器。",
      "description_en": "Clear device counters."
    },
    {
      "action_name": "set_sync_routing_master",
      "description": "将设备配置为同步路由主机。",
      "description_en": "Configure the device as the sync-routing master."
    },
    {
      "action_name": "set_sync_routing_slave",
      "description": "将设备配置为同步路由从机。",
      "description_en": "Configure the device as the sync-routing slave."
    },
    {
      "action_name": "set_sync_routing",
      "description": "设置设备的同步信号路由。",
      "description_en": "Set device synchronization routing."
    },
    {
      "action_name": "set_mb_clk",
      "description": "设置主背板时钟。",
      "description_en": "Set the main backplane clock."
    },
    {
      "action_name": "load_stl",
      "description": "载入时序或状态列表程序。",
      "description_en": "Load a timing or state-list program."
    },
    {
      "action_name": "load_gpg",
      "description": "载入通用模式发生器程序。",
      "description_en": "Load a general-purpose pattern generator program."
    },
    {
      "action_name": "load_dpg",
      "description": "载入数字模式发生器程序。",
      "description_en": "Load a digital pattern generator program."
    },
    {
      "action_name": "load_wrpg",
      "description": "载入 WR 模式发生器程序。",
      "description_en": "Load a WR pattern generator program."
    },
    {
      "action_name": "load_dio482pg",
      "description": "载入 DIO482 模式发生器程序。",
      "description_en": "Load a DIO482 pattern generator program."
    },
    {
      "action_name": "set_DO",
      "description": "设置数字输出电平。",
      "description_en": "Set digital output states."
    },
    {
      "action_name": "load_awg",
      "description": "载入任意波形发生器波形。",
      "description_en": "Load a waveform into the arbitrary waveform generator."
    },
    {
      "action_name": "set_segment",
      "description": "设置单个采集段参数。",
      "description_en": "Define parameters for a capture segment."
    },
    {
      "action_name": "run_service",
      "description": "启动设备上的指定服务。",
      "description_en": "Start a specified service on the device."
    }
  ]
}

